import React, { useMemo } from 'react';
import { Box, Button, Paper, Typography } from '@mui/material';
import {
  Assessment as AssessmentIcon,
  Description as DocumentsIcon,
  Summarize as ReportingIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';

type QuickAction = {
  label: string;
  path: string;
  icon: typeof AssessmentIcon;
};

/** Linear MSME core: Bills → Footprint → Report. */
const CORE_ACTIONS: QuickAction[] = [
  { label: 'Upload bills', path: '/document-upload', icon: DocumentsIcon },
  { label: 'Carbon footprint', path: '/carbon-footprint?section=start-assessment', icon: AssessmentIcon },
  { label: 'Pick report goal', path: '/reporting?tab=0', icon: ReportingIcon },
];

export interface DashboardQuickActionsProps {
  hasAssessment?: boolean;
  hasDocuments?: boolean;
  hasWorkflow?: boolean;
}

export const DashboardQuickActions: React.FC<DashboardQuickActionsProps> = ({
  hasAssessment = false,
}) => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  const actions = useMemo(() => CORE_ACTIONS, []);

  return (
    <Box>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
        Quick actions
      </Typography>
      <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1.5 }}>
        {hasAssessment
          ? 'Your next steps — bills, footprint, then one report goal.'
          : 'Start here: upload bills, see your footprint, pick one report goal.'}
      </Typography>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr',
            sm: 'repeat(3, 1fr)',
          },
          gap: 1.25,
        }}
      >
        {actions.map((action) => {
          const Icon = action.icon;
          return (
            <Paper
              key={action.path}
              component="button"
              type="button"
              onClick={() => navigate(action.path)}
              elevation={0}
              sx={{
                p: 1.5,
                textAlign: 'left',
                cursor: 'pointer',
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                bgcolor: isDark ? alpha(theme.palette.common.white, 0.03) : 'background.paper',
                transition: 'border-color 0.15s ease, background-color 0.15s ease',
                '&:hover': {
                  borderColor: 'primary.main',
                  bgcolor: alpha(theme.palette.primary.main, isDark ? 0.12 : 0.04),
                },
              }}
            >
              <Icon color="primary" fontSize="small" sx={{ mb: 0.75, display: 'block' }} />
              <Typography variant="body2" sx={{ fontWeight: 600, lineHeight: 1.3 }}>
                {action.label}
              </Typography>
            </Paper>
          );
        })}
      </Box>
      {hasAssessment ? (
        <Button
          size="small"
          variant="text"
          sx={{ mt: 1 }}
          onClick={() => navigate('/compliance')}
        >
          More tools in Compliance hub
        </Button>
      ) : null}
    </Box>
  );
};

export default DashboardQuickActions;
